/// The path the release commit adds or modifies that ends with `suffix`.
fn changed_path(root: &Path, release_commit: &str, suffix: &str) -> String {
    git(
        root,
        &[
            "diff-tree",
            "--no-commit-id",
            "--name-only",
            "-r",
            &format!("{release_commit}^"),
            release_commit,
        ],
    )
    .lines()
    .find(|path| path.ends_with(suffix))
    .unwrap_or_else(|| panic!("release commit changes no `{suffix}`"))
    .to_owned()
}

fn plan(root: &Path, external: &Path, commit: &str) -> Output {
    callisto(
        root,
        &[
            "release",
            "plan",
            "--from-release-commit",
            commit,
            "--decision",
            DECISION_PATH,
            "--out",
            external.join("intent.json").to_str().unwrap(),
        ],
    )
}

fn assert_rejected(root: &Path, external: &Path, commit: &str, what: &str, reason: &str) {
    let out = plan(root, external, commit);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(!out.status.success(), "{what} must be rejected: {stderr}");
    assert!(stderr.contains("E165"), "{what} must fail with E165: {stderr}");
    assert!(stderr.contains(reason), "{what} must fail because `{reason}`: {stderr}");
    assert!(
        !external.join("intent.json").exists(),
        "{what} must not leave an intent behind"
    );
}

#[test]
fn an_untampered_release_commit_still_plans() {
    let (dir, release_commit) = release_commit_fixture();
    let external = tempfile::tempdir().unwrap();
    let out = plan(dir.path(), external.path(), &release_commit);
    assert!(out.status.success(), "{}", String::from_utf8_lossy(&out.stderr));
}

#[test]
fn a_release_commit_in_a_workspace_below_the_repository_root_plans_and_still_refuses_edits_outside_it() {
    let (dir, release_commit) = release_commit_fixture_in(false, "ws");
    let root = dir.path();
    let runner = callisto_fixtures::git::GitRunner;
    let derive = |commit: &str| {
        let locator = callisto_graph::locate::IgnoreWalkLocator::new(&root.join("ws"));
        let workspace = callisto_graph::Workspace::load(root.join("ws"), &locator, &runner).unwrap();
        callisto_graph::commands::derive_release_commit_decision(
            &workspace,
            &callisto_model::CommitSha::parse(commit).unwrap(),
            Path::new(DECISION_PATH),
        )
    };
    derive(&release_commit).unwrap();

    let parent = git(root, &["rev-parse", &format!("{release_commit}^")]);
    git(root, &["checkout", "--detach", &parent]);
    git(root, &["checkout", &release_commit, "--", "."]);
    fs::write(root.join("build.rs"), "fn main() {}\n").unwrap();
    git(root, &["add", "-A"]);
    git(root, &["commit", "-q", "-m", "release with an edit outside the workspace"]);
    let tampered = git(root, &["rev-parse", "HEAD"]);
    git(root, &["checkout", "--detach", &tampered]);
    match derive(&tampered).unwrap_err() {
        callisto_graph::GraphError::ReleaseCommitVerificationFailed {
            reason: callisto_graph::error::CommitVerificationFailure::UnexpectedPath { path },
            ..
        } => assert_eq!(path, "../build.rs"),
        other => panic!("expected the outside edit to be refused, got {other:?}"),
    }
}

#[test]
fn a_commit_that_does_not_write_the_decision_is_rejected() {
    let (dir, release_commit) = release_commit_fixture();
    let root = dir.path();
    fs::write(root.join("crates/core/src/lib.rs"), "pub fn core() { /* later */ }\n").unwrap();
    git(root, &["commit", "-q", "-am", "unrelated follow-up"]);
    let follow_up = git(root, &["rev-parse", "HEAD"]);
    assert_ne!(follow_up, release_commit);
    let external = tempfile::tempdir().unwrap();
    assert_rejected(
        root,
        external.path(),
        &follow_up,
        "a commit that carries a stale decision",
        "release-decision file was not written",
    );
}

